<?php
declare(strict_types=1);
require_once __DIR__.'/PaymentTargets.php';
require_once __DIR__.'/RidePayments.php';
final class PaymentReconciliation
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private function tx(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    private static function text(mixed $value,int $min,int $max):string{if(!is_string($value)||str_contains($value,"\0"))throw new HttpError(400,'Thông tin đối soát không hợp lệ.');$s=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$value);$n=$s===null?-1:strlen(mb_convert_encoding($s,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)throw new HttpError(400,'Kiểm tra mã giao dịch, mã đơn hoặc ghi chú.');return $s;}
    private static function input(array $in,bool $resolve):array
    {
        if(array_diff(array_keys($in),$resolve?['eventId','targetCode','expectedAmount','note','verified']:['eventId','targetCode']))throw new HttpError(400,'Thông tin đối soát không hợp lệ.');$out=['eventId'=>self::text($in['eventId']??null,1,50),'targetCode'=>strtoupper(self::text($in['targetCode']??null,1,20))];if(!preg_match('/^SEPAY:LIVE:[0-9]{1,30}$/D',$out['eventId'])||!preg_match('/^(?:J[GMCBH][A-F0-9]{10}|JM-X[A-F0-9]{12})$/D',$out['targetCode']))throw new HttpError(400,'Nhập giao dịch SePay LIVE và mã vé WEB/JC/JB/JH. POS/CTV chưa mở đối soát.');
        if($resolve){if(($in['verified']??null)!==true||!is_int($in['expectedAmount']??null)||$in['expectedAmount']<1||$in['expectedAmount']>15000000000)throw new HttpError(400,'Xác nhận đã đối chiếu ngân hàng và đúng toàn bộ số tiền.');$out+=['expectedAmount'=>$in['expectedAmount'],'note'=>self::text($in['note']??null,5,500)];}return $out;
    }
    private function inspect(array $v):array
    {
        $event=$this->query('SELECT * FROM jingo_gateway_events WHERE id=? FOR UPDATE',[$v['eventId']])->fetch(PDO::FETCH_ASSOC);if(!$event)throw new HttpError(404,'Không tìm thấy giao dịch.');if($event['provider']!=='SEPAY'||$event['mode']!=='LIVE'||$event['status']!=='REVIEW'||(int)$event['amount']<1||(int)$event['amount']>15000000000)throw new HttpError(409,'Chỉ đối soát chuyển khoản SePay LIVE đang REVIEW và có số tiền hợp lệ.');if($this->query('SELECT event_id FROM jingo_gateway_resolutions WHERE event_id=?',[$v['eventId']])->fetchColumn())throw new HttpError(409,'Giao dịch đã được đối soát.');
        $s=str_starts_with($v['targetCode'],'JM-X')?['ride'=>(new RidePayments($this->db))->locked($v['targetCode']),'orders'=>[],'cart'=>null,'bundle'=>null]: (new PaymentTargets($this->db))->state($v['targetCode']);if(isset($s['ride']))$s['amount']=$s['ride']['total'];if($s['cart']&&count($s['orders'])!==(int)$this->query('SELECT COUNT(*) FROM jingo_cart_orders WHERE cart_id=?',[$s['cart']['id']])->fetchColumn())throw new HttpError(409,'Giỏ có gói đã thu, hủy hoặc lưu trữ. Không đối soát riêng phần còn lại.');if($s['amount']!==(int)$event['amount'])throw new HttpError(400,'Số tiền giao dịch phải bằng toàn bộ đơn. Không chia hoặc bù tiền.');if($this->query('SELECT reference_hash FROM jingo_payment_references WHERE reference_hash=?',[hash('sha256',$event['id'])])->fetchColumn())throw new HttpError(409,'Giao dịch đã có trong sổ thu.');foreach($s['orders'] as $o){$ref=$s['cart']?$event['id'].'#'.$o['code']:$event['id'];if($this->query('SELECT id FROM jingo_order_payments WHERE reference_hash=?',[hash('sha256',$ref)])->fetchColumn())throw new HttpError(409,'Tham chiếu thu đã được dùng.');}return ['event'=>$event,'state'=>$s];
    }
    public function preview(array $in):array
    {
        $v=self::input($in,false);return $this->tx(function()use($v){$r=$this->inspect($v);$s=$r['state'];$items=[];$customer='';if(isset($s['ride'])){$ride=$s['ride'];$d=$ride['data'];$customer=$d['contact']['name']??'';$items[]=['code'=>$ride['row']['code'],'productName'=>($d['fromName']??'').' → '.($d['toName']??''),'variantName'=>$d['vehicleName']??'','date'=>$ride['row']['visit_date'],'total'=>$ride['total']];}elseif(isset($s['hotel'])){$h=$s['hotel'];$d=$h['data'];$customer=$d['contact']['name'];$items[]=['code'=>$h['row']['code'],'productName'=>$d['hotelName'],'variantName'=>$d['roomName'],'date'=>$h['row']['check_in'].' → '.$h['row']['check_out'],'total'=>$h['total']];}else{foreach($s['orders'] as $o){$d=json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR);$items[]=['code'=>$o['code'],'productName'=>$d['productName'],'variantName'=>$d['variantName'],'date'=>$d['date'],'total'=>$d['total']];}if($s['bundle']){$d=json_decode($s['bundle']['data'],true,512,JSON_THROW_ON_ERROR);$customer=$d['contact']['name']??'';$raw=(new CheckoutBundles($this->db))->gatewayState($s['bundle']['id']);foreach(['ride'=>'Xe','gift'=>'Quà & phí giao'] as $key=>$label)if($raw[$key]??null){$row=$raw[$key];$data=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$items[]=['code'=>$row['code'],'productName'=>$label,'variantName'=>'','date'=>$row['visit_date']??'','total'=>$data['total']];}}elseif($s['orders'])$customer=json_decode($s['orders'][0]['contact'],true,512,JSON_THROW_ON_ERROR)['name'];}return ['eventId'=>$v['eventId'],'targetCode'=>$v['targetCode'],'amount'=>$s['amount'],'customerName'=>$customer,'items'=>$items,'reason'=>$r['event']['reason']];});
    }
    public function resolve(array $in,string $actor):array
    {
        $v=self::input($in,true);if($actor===''||str_starts_with($actor,'gateway:'))throw new LogicException('Reconciliation requires an admin actor.');return $this->tx(function()use($v,$actor){$event=$this->query('SELECT amount FROM jingo_gateway_events WHERE id=? FOR UPDATE',[$v['eventId']])->fetch(PDO::FETCH_ASSOC);if(!$event)throw new HttpError(404,'Không tìm thấy giao dịch.');$prior=$this->query('SELECT target_code FROM jingo_gateway_resolutions WHERE event_id=?',[$v['eventId']])->fetchColumn();if($prior!==false){if($prior!==$v['targetCode']||(int)$event['amount']!==$v['expectedAmount'])throw new HttpError(409,'Giao dịch đã được gắn vào đơn khác hoặc số tiền không khớp.');return ['ok'=>true,'alreadyResolved'=>true,'targetCode'=>$prior];}$r=$this->inspect($v);$s=$r['state'];if($s['amount']!==$v['expectedAmount'])throw new HttpError(409,'Số tiền đã thay đổi. Kiểm tra lại trước khi xác nhận.');
            if(isset($s['ride']))(new RidePayments($this->db))->credit($s['ride'],$v['eventId'],$actor);else (new PaymentTargets($this->db))->credit($s,$v['eventId'],'SEPAY',$actor);$this->query('DELETE FROM jingo_ride_payment_events WHERE event_id=?',[$v['eventId']]);if(isset($s['ride']))$this->query('INSERT INTO jingo_ride_payment_events(event_id,ride_id) VALUES (?,?)',[$v['eventId'],$s['ride']['row']['id']]);$this->query('DELETE FROM jingo_stay_payment_events WHERE event_id=?',[$v['eventId']]);if(isset($s['hotel']))$this->query('INSERT INTO jingo_stay_payment_events(event_id,booking_id) VALUES (?,?)',[$v['eventId'],$s['hotel']['row']['id']]);$this->query('INSERT INTO jingo_gateway_resolutions(event_id,target_code,admin_id,note,original_reason,original_order_id) VALUES (?,?,?,?,?,?)',[$v['eventId'],$v['targetCode'],$actor,$v['note'],$r['event']['reason'],$r['event']['order_id']]);$this->query("UPDATE jingo_gateway_events SET order_id=?,status='PAID',reason=? WHERE id=?",[$s['orders'][0]['id']??null,'Đã đối soát '.$v['targetCode'].': '.$v['note'],$v['eventId']]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,isset($s['hotel'])?'stay.reconcile':(isset($s['ride'])?'ride.reconcile':'payments.reconcile'),isset($s['hotel'])?$s['hotel']['row']['id']:(isset($s['ride'])?$s['ride']['row']['id']:$v['eventId'])]);return ['ok'=>true,'targetCode'=>$v['targetCode']];});
    }
}
